  "untestable": 0.1,
  "artifact": 0.25,
  "uncertain": 0.35
 },
 "decision": "do_not_proceed",
 "design": {
  "estimand": "Conditional on a pre-registered AVOID definition that does not use the next-possession outcome, the difference in opponent next-possession PPP after play X versus matched baseline possessions, and the incremental effect of own-sequence lags. The estimate is conditional on the label passing validation.",
